window.PP_BANKS=window.PP_BANKS||{};window.PP_BANKS["econ-150-ch18"]={"schema":"precise-practice/1","bank_id":"econ-150-ch18","book":"econ-150","chapter":18,"title":"Chapter 18 practice: The Tragedy of the Commons","storage_version":1,"status":"prototype","blueprint":"docs/blueprints/econ-150-ch17-18.md","settings":{"goals":{"1":10,"2":5,"3":3}},"concepts":[{"id":"c1","number":1,"name":"The Four Kinds of Goods","activities":[{"id":"c1-sort-four","type":"sort","tier":1,"title":"Sort the goods","targets":["18.1a"],"status":"prototype","bins":["Private good","Club good (quasi-public)","Common resource","Public good"],"round_size":4,"cards":[{"id":"E18-C1-FG01","text":"A slice of pizza","bin":0,"why":"You can be charged for it, and once you eat it, no one else can.","bin_misconceptions":[null,"M18-01","M18-01","M18-05"],"_v":"a6c1b30e56"},{"id":"E18-C1-FG02","text":"Cable TV","bin":1,"why":"Non-payers can be cut off, but one more viewer doesn't use up the signal. Quizzes may call this a quasi-public or artificially scarce good.","bin_misconceptions":["M18-01",null,"M18-05","M18-06"],"_v":"8a4d3470a2"},{"id":"E18-C1-FG03","text":"Groundwater under farmland that anyone can pump","bin":2,"why":"No one can be kept from pumping, and every gallon pumped leaves less for others.","bin_misconceptions":["M18-02","M18-05",null,"M18-01"],"_v":"08e10440c4"},{"id":"E18-C1-FG04","text":"A city's fireworks show","bin":3,"why":"Anyone nearby can watch, and one more viewer doesn't take anything away from the others.","bin_misconceptions":["M18-02","M18-01","M18-05",null],"_v":"c2bc929375"},{"id":"E18-C1-FG05","text":"A public library that lets anyone walk in","bin":3,"why":"A library could check cards, but it chooses not to, so it behaves like a non-excludable good. Quizzes usually treat it that way (see Chapter 16).","bin_misconceptions":["M18-02","M18-02","M18-05",null],"_v":"65c163764f"}]},{"id":"c1-compare","type":"compare","tier":1,"title":"Which is easier to exclude?","targets":["18.1a"],"status":"prototype","round_size":2,"items":[{"id":"E18-C1-CP01","prompt":"Which is easier to keep non-payers away from?","left":"A movie theater","right":"An open ocean fishery","answer":0,"why":"A theater can check tickets at the door. No one can stop boats on the open ocean.","option_misconceptions":[null,"M18-01"],"_v":"e2cf1737de"},{"id":"E18-C1-CP02","prompt":"Which is easier to keep non-payers away from?","left":"Clean air in a city","right":"A gym","answer":1,"why":"A gym can require a membership. No one can be kept from breathing city air.","option_misconceptions":["M18-01",null],"_v":"aa86153efd"}]},{"id":"c1-response","type":"choice","tier":2,"title":"Which response fits?","targets":["18.1b"],"status":"prototype","items":[{"id":"E18-C1-RF01","prompt":"A town's mosquito spraying protects everyone, but no private company will do it because it can't charge people who don't pay. What's the usual economic response?","options":["Pay for it with taxes or subsidize a provider, because it's a public good.","Limit how much each household can use, because it's a common resource.","Let the market handle it, because it's a private good.","Charge a membership fee, because it's a club good."],"answer":0,"why":"Spraying is non-excludable and non-rival, so free riders mean too little gets provided. The fix is to pay for it together.","option_misconceptions":[null,"M18-05","M18-01","M18-02"],"_v":"835a215bcc"}]}]},{"id":"c2","number":2,"name":"The Commons Trap","activities":[{"id":"c2-applied","type":"choice","tier":2,"title":"Applied cases","targets":["18.2a"],"status":"prototype","items":[{"id":"E18-C2-AC01","prompt":"Farmers in a valley all pump from the same underground aquifer, and the water table falls a little more every year. Which explanation fits best?","options":["The water is rival and no one can be kept from pumping, so each farmer pumps more than is good for the group.","The farmers don't understand that the water can run out.","The water is a public good, so no one has a reason to supply it.","The farmers are greedier than people in other valleys."],"answer":0,"why":"Each farmer gets all the benefit of pumping more but shares the cost of a lower water table with everyone. That's the commons trap, and it works even on farmers who know exactly what's happening.","option_misconceptions":[null,"M18-03","M18-05","M18-03"],"_v":"008b1ff07f"}]}]},{"id":"c3","number":3,"name":"The Incentive to Overuse","activities":[{"id":"c3-predict","type":"choice","tier":2,"title":"What changes?","targets":["18.3a"],"status":"prototype","items":[{"id":"E18-C3-PR01","prompt":"A popular hiking trail has no limit on visitors. One more hiker would enjoy the trail, but adds a little crowding and erosion. What does that hiker do, and why?","options":["Goes anyway, because the hiker gets the whole benefit and pays only a tiny share of the crowding and erosion.","Stays home, because the hiker can see the trail is wearing out.","Goes only if a ranger approves, because trails are public goods.","Pays the other hikers for the crowding, because that's fair."],"answer":0,"why":"The private cost to the hiker is lower than the social cost. That's the same gap that empties a fishery.","option_misconceptions":[null,"M18-03","M18-05",null],"_v":"f3d9cc86ad"}]},{"id":"c3-ap","type":"choice","tier":3,"title":"Quiz-style questions","targets":["18.3a"],"status":"prototype","items":[{"id":"E18-C3-AP01","prompt":"Ranchers graze cattle on open public land, and the grass is badly overgrazed. It is rational for an individual rancher to keep grazing rather than conserve the grass because","options":["the private cost of grazing is lower than the social cost","the social cost of grazing is lower than the private cost","the private benefit of grazing is lower than the social benefit","grass is a public good"],"answer":0,"why":"Each rancher pays only a sliver of the cost of thinner grass; the rest falls on every other rancher. That's a negative externality inside the commons.","option_misconceptions":[null,"M18-07","M17-04","M18-05"],"_v":"41f397739f"}]},{"id":"c3-tiles","type":"tiles","tier":2,"title":"Economics ↔ English","targets":["18.3a"],"status":"prototype","items":[{"id":"E18-C3-TL01","title":"Nobody cares about the lake.","prompt":"Every boat keeps fishing even though the lake is emptying. What would an economist actually say?","correct":["Each boat gets the full benefit of its catch","but shares the cost of a smaller stock with every other boat"],"wrong":["The fishers don't care about the future","The fish are a public good"],"why":"The problem is the incentive, not the people. A fisher who cares a lot about the lake still can't save it alone.","hint":"Who gets the benefit, and who pays the cost?","wrong_misconceptions":["M18-03","M18-05"],"_v":"8a376cd597"}]}]},{"id":"c4","number":4,"name":"Fences and Rules","activities":[{"id":"c4-sort","type":"sort","tier":1,"title":"What kind of fix?","targets":["18.4a"],"status":"prototype","bins":["Give it an owner","Set a rule or cap","The users govern it"],"round_size":3,"cards":[{"id":"E18-C4-FX01","text":"A country gives each fishing firm a tradable share of the total catch.","bin":0,"why":"Tradable shares work like ownership: each firm owns a slice and gains from protecting the stock.","bin_misconceptions":[null,null,null],"_v":"b6d7b50c0d"},{"id":"E18-C4-FX02","text":"A state limits each farmer to 200 acre-feet of groundwater a year.","bin":1,"why":"A limit set and enforced from outside is a rule or cap.","bin_misconceptions":[null,null,null],"_v":"0a60a260d5"},{"id":"E18-C4-FX03","text":"Families in a mountain village write their own grazing rules and fine anyone who breaks them.","bin":2,"why":"The users make and enforce the rules themselves, the kind of case Elinor Ostrom studied.","bin_misconceptions":["M18-04","M18-04",null],"_v":"74b4a5f301"}]}]},{"id":"c5","number":5,"name":"Ostrom and Self-Governance","activities":[{"id":"c5-match","type":"match","tier":1,"title":"Memory Match: Ostrom's principles","targets":["18.5a"],"status":"prototype","board_size":4,"pairs":[{"id":"E18-C5-MM01","left":"Clear boundaries","right":"Everyone knows who may use the resource and where it ends.","_v":"d806d319ff"},{"id":"E18-C5-MM02","left":"Monitoring","right":"Someone answerable to the users watches how much each one takes.","_v":"d014b36837"},{"id":"E18-C5-MM03","left":"Graduated sanctions","right":"A first offense gets a small penalty; repeat offenses get bigger ones.","_v":"b885922f8f"},{"id":"E18-C5-MM04","left":"Outside recognition","right":"Higher authorities respect the users' right to make their own rules.","_v":"a3052e8449"}]}]}],"readiness":{"streak":2,"items":[{"id":"E18-RD01","prompt":"A good that is non-excludable and rival in use is","options":["a common resource","a public good","a club good","a private good"],"answer":0,"why":"No one can be kept out, and each use leaves less for others.","option_misconceptions":[null,"M18-01","M18-01","M18-02"],"_v":"4eeeae56d9"},{"id":"E18-RD02","prompt":"Which is the best example of a quasi-public (artificially scarce) good?","options":["A streaming service","Ocean tuna","National defense","A sandwich"],"answer":0,"why":"A streaming service can block non-payers, but one more viewer uses up almost nothing. That's a club good, which quizzes may call quasi-public or artificially scarce.","option_misconceptions":[null,"M18-01","M18-06","M18-01"],"_v":"2151667d26"}],"spiral":[]},"version":"6887d76f4d"};
